INSERT INTO recipe_ingredients (id, recipe_id, name, quantity, unit, notes, order_index, created_at, is_deleted) VALUES ('44444444-4444-4444-0100-00000009', '33333333-3333-3333-3333-000000000100', 'Nấm hương khô thơm', 55.0, 'g', 'Ngâm nở thái chỉ', 9, NOW(), false) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipe_ingredients (id, recipe_id, name, quantity, unit, notes, order_index, created_at, is_deleted) VALUES ('44444444-4444-4444-0100-00000010', '33333333-3333-3333-3333-000000000100', 'Xì dầu đậu nành nguyên chất', 3.0, 'muỗng canh', 'Loại ủ lên men tự nhiên', 10, NOW(), false) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) VALUES ('55555555-5555-5555-0001-00000001', '33333333-3333-3333-3333-000000000001', 1, 'Bước 1: Sơ chế nguyên liệu tươi', 'Rửa sạch tất cả thịt cá và rau củ với nước muối loãng. Thịt thấm khô bằng khăn giấy chuyên dụng trước khi tẩm ướp. Rau thơm nhặt lá non, để thật ráo nước.', 10, NOW(), false) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) VALUES ('55555555-5555-5555-0001-00000002', '33333333-3333-3333-3333-000000000001', 2, 'Bước 2: Pha chế sốt ướp bí truyền', 'Cho tỏi băm, hành phi, nước mắm ngon, tiêu đen, mật ong và dầu hào vào âu lớn. Khuấy đều tay đến khi các gia vị tan hoàn toàn và hòa quyện thành hỗn hợp sánh mịn.', 8, NOW(), false) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) VALUES ('55555555-5555-5555-0001-00000003', '33333333-3333-3333-3333-000000000001', 3, 'Bước 3: Tẩm ướp thấm đượm gia vị', 'Trút phần thịt vào âu gia vị sốt ướp, dùng tay mát xa nhẹ nhàng từng thớ thịt. Đậy kín màng bọc thực phẩm và giữ trong ngăn mát tủ lạnh ít nhất 30-45 phút.', 35, NOW(), false) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) VALUES ('55555555-5555-5555-0001-00000004', '33333333-3333-3333-3333-000000000001', 4, 'Bước 4: Hầm nước dùng / Ninh lửa nhỏ', 'Bắc nồi lên bếp, cho xương đã chần và túi thảo mộc thơm vào cùng 2 lít nước sôi. Hạ lửa nhỏ liu riu, thường xuyên hớt bọt để nước trong suốt óng ả.', 60, NOW(), false) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) VALUES ('55555555-5555-5555-0001-00000005', '33333333-3333-3333-3333-000000000001', 5, 'Bước 5: Chế biến nhiệt / Xào nấu chín tới', 'Làm nóng chảo sâu lòng với chút mỡ hành hoặc dầu ăn. Trút nguyên liệu vào đảo nhanh tay trên lửa lớn đến khi săn lại, dậy mùi thơm nức mũi và giữ trọn độ mọng nước.', 15, NOW(), false) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) VALUES ('55555555-5555-5555-0001-00000006', '33333333-3333-3333-3333-000000000001', 6, 'Bước 6: Nêm nếm hoàn thiện hương vị', 'Nếm thử nước sốt, điều chỉnh lượng nước mắm và đường phèn sao cho đạt độ cân bằng tuyệt đối giữa mặn, ngọt, chua thanh và the cay nhẹ nơi đầu lưỡi.', 5, NOW(), false) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) VALUES ('55555555-5555-5555-0001-00000007', '33333333-3333-3333-3333-000000000001', 7, 'Bước 7: Trình bày và thưởng thức', 'Múc món ăn ra đĩa hoặc tô gốm mộc nóng hổi. Rắc thêm tiêu sọ xay vỡ, hành phi vàng óng và nhánh rau mùi tươi lên trên. Dùng ngay khi còn nóng để cảm nhận trọn vẹn tinh hoa ẩm thực.', 5, NOW(), false) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) VALUES ('55555555-5555-5555-0002-00000001', '33333333-3333-3333-3333-000000000002', 1, 'Bước 1: Sơ chế nguyên liệu tươi', 'Rửa sạch tất cả thịt cá và rau củ với nước muối loãng. Thịt thấm khô bằng khăn giấy chuyên dụng trước khi tẩm ướp. Rau thơm nhặt lá non, để thật ráo nước.', 10, NOW(), false) ON CONFLICT (id) DO NOTHING;
