INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) VALUES ('55555555-5555-5555-0016-00000006', '33333333-3333-3333-3333-000000000016', 6, 'Bước 6: Nêm nếm hoàn thiện hương vị', 'Nếm thử nước sốt, điều chỉnh lượng nước mắm và đường phèn sao cho đạt độ cân bằng tuyệt đối giữa mặn, ngọt, chua thanh và the cay nhẹ nơi đầu lưỡi.', 5, NOW(), false) ON CONFLICT (id) DO NOTHING;
