INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) VALUES ('55555555-5555-5555-0044-00000001', '33333333-3333-3333-3333-000000000044', 1, 'Bước 1: Sơ chế nguyên liệu tươi', 'Rửa sạch tất cả thịt cá và rau củ với nước muối loãng. Thịt thấm khô bằng khăn giấy chuyên dụng trước khi tẩm ướp. Rau thơm nhặt lá non, để thật ráo nước.', 10, NOW(), false) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) VALUES ('55555555-5555-5555-0044-00000002', '33333333-3333-3333-3333-000000000044', 2, 'Bước 2: Pha chế sốt ướp bí truyền', 'Cho tỏi băm, hành phi, nước mắm ngon, tiêu đen, mật ong và dầu hào vào âu lớn. Khuấy đều tay đến khi các gia vị tan hoàn toàn và hòa quyện thành hỗn hợp sánh mịn.', 8, NOW(), false) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) VALUES ('55555555-5555-5555-0044-00000003', '33333333-3333-3333-3333-000000000044', 3, 'Bước 3: Tẩm ướp thấm đượm gia vị', 'Trút phần thịt vào âu gia vị sốt ướp, dùng tay mát xa nhẹ nhàng từng thớ thịt. Đậy kín màng bọc thực phẩm và giữ trong ngăn mát tủ lạnh ít nhất 30-45 phút.', 35, NOW(), false) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) VALUES ('55555555-5555-5555-0044-00000004', '33333333-3333-3333-3333-000000000044', 4, 'Bước 4: Hầm nước dùng / Ninh lửa nhỏ', 'Bắc nồi lên bếp, cho xương đã chần và túi thảo mộc thơm vào cùng 2 lít nước sôi. Hạ lửa nhỏ liu riu, thường xuyên hớt bọt để nước trong suốt óng ả.', 60, NOW(), false) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) VALUES ('55555555-5555-5555-0044-00000005', '33333333-3333-3333-3333-000000000044', 5, 'Bước 5: Chế biến nhiệt / Xào nấu chín tới', 'Làm nóng chảo sâu lòng với chút mỡ hành hoặc dầu ăn. Trút nguyên liệu vào đảo nhanh tay trên lửa lớn đến khi săn lại, dậy mùi thơm nức mũi và giữ trọn độ mọng nước.', 15, NOW(), false) ON CONFLICT (id) DO NOTHING;
