INSERT INTO recipe_steps (id, recipe_id, step_number, title, description, timer_minutes, created_at, is_deleted) VALUES ('55555555-5555-5555-0093-00000007', '33333333-3333-3333-3333-000000000093', 7, 'Bước 7: Trình bày và thưởng thức', 'Múc món ăn ra đĩa hoặc tô gốm mộc nóng hổi. Rắc thêm tiêu sọ xay vỡ, hành phi vàng óng và nhánh rau mùi tươi lên trên. Dùng ngay khi còn nóng để cảm nhận trọn vẹn tinh hoa ẩm thực.', 5, NOW(), false) ON CONFLICT (id) DO NOTHING;
